window.RP_SESSION={"id":"S-7d96794c8a2a","messages":[{"id":"Plane-0003349","time":"2026-09-26T18:15:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"으아으으....\"\n\n뻐근한 어깨 풀며 쭉쭉... 스트레칭합니다\n\n\"뼈라서 굳었남...\"\n\n허리를 쭉 돌리니 뚝- 하는 소리가 불안하지만...\n\n발목도 요리조리 돌려보고 손목도 돌려보며 스트레칭을 이어합니다","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003350","time":"2026-09-26T18:17:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"마리,..우스씨도 한참 안들어오시고...\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003351","time":"2026-09-26T18:17:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"먼지 쌓인 이불은 탁탁 털어놔줍니다","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003352","time":"2026-09-26T18:18:00+09:00","room":"Plane","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"호랑이도 제말하면 온다.\n\n벌컥.\n\n마리우스가 기숙사 문을 열었습니다.\n\n“ 켁, 앗, 마리아. 먼지 털구 잌, 켁. ”","characters":["P-b6d81d634c6e"]},{"id":"Plane-0003353","time":"2026-09-26T18:19:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"힉! ....엇...\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003354","time":"2026-09-26T18:19:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"ㄱ그... 먼지이이이ㅣㅣ....털구..있었어요..\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003355","time":"2026-09-26T18:20:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"후다닥.. 급하게 이불을 개어 침대 위에 올려두었습니다\n\n\"오랜만이에요..!\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003356","time":"2026-09-26T18:24:00+09:00","room":"Plane","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아, 네, 오랜만이에요. 이래저래 많이 바빴더니 볼 일이 적어졌네···. ”\n\n손으로 코 근처에 바람을 휙휙 불어 먼지를 밀어냅니다.\n\n“ 잘 지냈어요? ”","characters":["P-b6d81d634c6e"]},{"id":"Plane-0003357","time":"2026-09-26T18:26:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"전 잘 지냈어요! 그럭저럭 지냈고...\"\n\n\"마리우스씨는 근대 어디 다녀오신 거에요?\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003358","time":"2026-09-26T18:43:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"션씨랑 둘이 가서 한참 안 오시고... 저 혼자 깨 있느라 얼마나 심심했는데요\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003359","time":"2026-09-26T19:22:00+09:00","room":"Plane","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아, 토팔이요. 남부 쪽에 다녀왔어요. 음···. 후견자와 관련된 일이 있는 것 같아서요. ”\n\n“ 해결하고 어제 돌아왔어요. 마리아는 제가 없는 동안 잘···. 있었어요? ”","characters":["P-b6d81d634c6e"]},{"id":"Plane-0003360","time":"2026-09-26T19:27:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"에? 후겭... 아, 아..~ 그랬죠\"\n\n\"...흐흐, 저 있죠... 저 말이죠...\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003361","time":"2026-09-26T19:28:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"저 있잖아요오오...!!!\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003362","time":"2026-09-26T19:29:00+09:00","room":"Plane","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"응? 마리우스가 짐을 내려놓고 돌아 마리아를 바라봅니다.","characters":["P-b6d81d634c6e"]},{"id":"Plane-0003363","time":"2026-09-26T19:32:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"... 저! 저 어제 결혼했다구요! 짱이죠 마리우스 씨!\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003364","time":"2026-09-26T19:32:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003365","time":"2026-09-26T19:32:00+09:00","room":"Plane","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"아.","characters":["P-b6d81d634c6e"]},{"id":"Plane-0003366","time":"2026-09-26T19:32:00+09:00","room":"Plane","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"···.","characters":["P-b6d81d634c6e"]},{"id":"Plane-0003367","time":"2026-09-26T19:35:00+09:00","room":"Plane","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"마리우스의 표정이 잠시 변해갑니다.\n\n마리아가 본다면, 당연히 부정적인 감정임을 알았겠지요. 최대한 웃음짓고, 찡그리지 않아야 합니다.\n\n그러나···.\n\n“ 축하해요, 마리아. ”\n\n“ 근데, 이 얘긴 나중에 할까요? “\n\n축하가 축하처럼 느껴지지 않을 겁니다.","characters":["P-b6d81d634c6e"]},{"id":"Plane-0003368","time":"2026-09-26T19:35:00+09:00","room":"Plane","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"마리아의 입장에서는···. 불공평 할 수도 있고요.\n\n수많은 축하를 해주었던 마리우스에게 이 얘긴 나중에 하자는 말을 들었다면···.","characters":["P-b6d81d634c6e"]},{"id":"Plane-0003369","time":"2026-09-26T19:36:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...ㅇ에? 왜... 그.. 알았어요\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003370","time":"2026-09-26T19:38:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"ㅇ에헤..... 무슨 일 있었어요...?\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003371","time":"2026-09-26T19:38:00+09:00","room":"Plane","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"마리우스가 여전히 짐정리를 하고 있습니다. 고요하게···.","characters":["P-b6d81d634c6e"]},{"id":"Plane-0003372","time":"2026-09-26T19:38:00+09:00","room":"Plane","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아뇨. ”\n\n“ 없었어요. ”","characters":["P-b6d81d634c6e"]},{"id":"Plane-0003373","time":"2026-09-26T19:38:00+09:00","room":"Plane","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"단답만 내뱉고서, 다시 짐 정리에 집중합니다.","characters":["P-b6d81d634c6e"]},{"id":"Plane-0003374","time":"2026-09-26T19:39:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"... ㅈ저... 그게...\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003375","time":"2026-09-26T19:40:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"... ㅎ화났어요..?\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003376","time":"2026-09-26T19:42:00+09:00","room":"Plane","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아뇨, 마리아···. ”\n\n남의 축복을 받아들일 수 없는 상황인 걸요. 어제 내가 무엇을 잃었는데, 내가 어떻게···. 그걸.\n\n“ 화 안 났어요. 그냥···. ”\n\n한숨을 내쉽니다. 복통이 쥐어짜듯 몰려옵니다.\n\n“ 아니에요. 아무것도. “","characters":["P-b6d81d634c6e"]},{"id":"Plane-0003377","time":"2026-09-26T19:43:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"살짝 표정을 살폈습니다\n\n\".. 어디 아픈데..있어요?\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003378","time":"2026-09-26T19:44:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"그런거면 제가..!\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003379","time":"2026-09-26T19:46:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...도와..드릴게요...?\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003380","time":"2026-09-26T19:51:00+09:00","room":"Plane","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아뇨! 마리아. 하나도 없어요. ”\n\n“ 그만하자고 하잖아요! ”\n\n마리우스가 손에 들었던 가방을 꾹 쥐어내고 소리칩니다. 거친 숨을 내뱉고. 입술을 꾹 물었습니다.\n\n남의 좋은 일을 축하해주지 못하는 자신이 너무···. 싫습니다. 제 일과 비교하여 삿대질하는 자신이 너무 싫어요.","characters":["P-b6d81d634c6e"]},{"id":"Plane-0003381","time":"2026-09-26T19:52:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"!..... ㄴ나쁜.... 의도가 아니라아...\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003382","time":"2026-09-26T19:53:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\".....ㅁ미안.....해요...\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003383","time":"2026-09-26T19:55:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"아..! 짐정리... 도와드릴까요...?\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003384","time":"2026-09-26T20:06:00+09:00","room":"Plane","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ ······. ”\n\n“ 아뇨, 나, 생각 좀 정리하고 올게요. ”\n\n마리우스가 짐가방을 휙 던져놓고. 몸을 돌려 문고리를 잡습니다.","characters":["P-b6d81d634c6e"]},{"id":"Plane-0003385","time":"2026-09-26T20:10:00+09:00","room":"Plane","name":"마리아","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"ㅁ마리우스... 언니이...\"\n\n\"...... ㅇ알갰어요...! 너무 그.. 늦개 오진 말고...\"","characters":["P-c9505ea97ebc"]},{"id":"Plane-0003386","time":"2026-09-26T20:12:00+09:00","room":"Plane","name":"시스템","profile":"","identity":"system","type":"system","body":"아킬레스 리귀론님이 들어왔습니다.","characters":[]},{"id":"Plane-0003387","time":"2026-09-26T20:12:00+09:00","room":"Plane","name":"안내 봇","profile":"오픈채팅봇","identity":"bot","type":"bot","body":"안녕하세요, RP room IV\n어설픈 용맹 Plane입니다.\n\n이곳은 《운명의 굴레》비참여 공간 입니다.","characters":[]},{"id":"Plane-0003388","time":"2026-09-26T20:19:00+09:00","room":"Plane","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"··· 마리우스가 조용히 문을 닫고 나섭니다.","characters":["P-b6d81d634c6e"]},{"id":"Plane-0003389","time":"2026-09-26T20:19:00+09:00","room":"Plane","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b6d81d634c6e"]}]};
